import { ColumnInstance } from 'react-table';

import { DATA_TABLE_DEFAULT_MIN_COLUMN_WIDTH } from '../../DataTable/constants.js';

/**
 * Filters out header group entries from the resizedColumnWidths array.
 * @param resizedColumnWidths - all column width entries including header groups. This array is not modified by this function.
 * @param headers - instance column headers
 * @returns filtered header widths.
 */
export function filterHeaderGroupWidths(
  resizedColumnWidths: Record<string, number>,
  headers: ColumnInstance[],
): Record<string, number> {
  const filteredColumnWidths = { ...resizedColumnWidths };
  // get all header group ids
  const headerGroupIds = headers.flatMap((header) =>
    header.columns ? header.id : [],
  );
  // remove header group ids from the column widths object
  headerGroupIds.forEach((key) => {
    delete filteredColumnWidths[key];
  });
  return filteredColumnWidths;
}

/**
 * Ensures all column widths are between column min and max.
 * @param columnWidths - these widths are checked.
 * @param allColumns - all column objects (for getting min and max).
 * @returns columnWidths except with values clamped between min and max.
 */
export function clampAll(
  columnWidths: Record<string, number>,
  // eslint-disable-next-line @typescript-eslint/ban-types
  allColumns: { id: string; minWidth?: number; maxWidth?: number }[],
): Record<string, number> {
  const clampedColumnWidths = { ...columnWidths };
  for (const key of Object.keys(clampedColumnWidths)) {
    const col = allColumns.find((curr) => curr.id === key);
    if (col !== undefined) {
      clampedColumnWidths[key] = clamp(
        clampedColumnWidths[key],
        col.minWidth ?? DATA_TABLE_DEFAULT_MIN_COLUMN_WIDTH,
        col.maxWidth ?? Number.MAX_SAFE_INTEGER,
      );
    } else {
      // eslint-disable-next-line no-console
      console.warn(`Column ${key} not found. This should not happen.`);
      clampedColumnWidths[key] = clamp(
        clampedColumnWidths[key],
        DATA_TABLE_DEFAULT_MIN_COLUMN_WIDTH,
        Number.MAX_SAFE_INTEGER,
      );
    }
  }
  return clampedColumnWidths;
}

function clamp(num: number, min: number, max: number): number {
  return num <= min ? min : num >= max ? max : num;
}
